<?php
require 'auth.php';require_login();require 'db.php';require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['review'])&&$_SESSION['role']==='volunteer'){$id=(int)$_POST['review'];$status=$_POST['decision']==='approved'?'approved':'rejected';$uid=$_SESSION['user_id'];$s=$conn->prepare('UPDATE adoption_request SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE adoption_id=?');$s->bind_param('sii',$status,$uid,$id);$s->execute();if($status==='approved'){$q=$conn->prepare("UPDATE animal a JOIN adoption_request ar ON a.animal_id=ar.animal_id SET a.status='adopted' WHERE ar.adoption_id=?");$q->bind_param('i',$id);$q->execute();}header('Location: adoptions.php?msg='.urlencode('Adoption request '.$status.'.'));exit;}
 $animal=(int)($_POST['animal_id']??0);$food=trim($_POST['food_habit']??'');$home=trim($_POST['home_details']??'');$uid=$_SESSION['user_id'];$s=$conn->prepare('INSERT INTO adoption_request(animal_id,adopter_id,food_habit,home_details) VALUES(?,?,?,?)');$s->bind_param('iiss',$animal,$uid,$food,$home);$s->execute();header('Location: adoptions.php?msg='.urlencode('Adoption request submitted.'));exit;
}
$animals=$conn->query("SELECT animal_id,name FROM animal WHERE status IN ('available','rescued','under_treatment') ORDER BY name");$where=$_SESSION['role']==='volunteer'?'1=1':'ar.adopter_id='.(int)$_SESSION['user_id'];$reqs=$conn->query("SELECT ar.*,a.name animal_name,u.full_name adopter FROM adoption_request ar JOIN animal a ON ar.animal_id=a.animal_id JOIN users u ON ar.adopter_id=u.user_id WHERE $where ORDER BY ar.adoption_id DESC");page_top('Adoptions');
?><div class="section-head"><h1 class="page-title">Adoption Center</h1></div><form class="form-card form-grid" method="post"><select name="animal_id" required><option value="">Choose animal</option><?php while($a=$animals->fetch_assoc()):?><option value="<?=$a['animal_id']?>" <?=((int)($_GET['animal_id']??0)==$a['animal_id'])?'selected':''?>><?=h($a['name'])?></option><?php endwhile;?></select><input name="food_habit" placeholder="How will you feed the animal?" required><textarea class="full" name="home_details" rows="4" placeholder="Tell us about your home, other pets, and care plan"></textarea><button class="btn full">Request Adoption ❤️</button></form><div class="section-head"><h2><?=$_SESSION['role']==='volunteer'?'All adoption requests':'My adoption requests'?></h2></div><div class="table-wrap"><table><tr><th>ID</th><th>Animal</th><th>Adopter</th><th>Food habit</th><th>Status</th><th>Action</th></tr><?php while($r=$reqs->fetch_assoc()):?><tr><td>#<?=$r['adoption_id']?></td><td><?=h($r['animal_name'])?></td><td><?=h($r['adopter'])?></td><td><?=h($r['food_habit'])?></td><td><span class="tag"><?=h($r['status'])?></span></td><td><?php if($_SESSION['role']==='volunteer'&&$r['status']==='pending'):?><form method="post" class="actions"><input type="hidden" name="review" value="<?=$r['adoption_id']?>"><button class="btn small" name="decision" value="approved">Approve</button><button class="btn small danger" name="decision" value="rejected">Reject</button></form><?php else:?>—<?php endif;?></td></tr><?php endwhile;?></table></div><?php page_bottom(); ?>
